import React, { useEffect, useState } from 'react';
import { getRequests } from '../services/requestService';
import { Link } from 'react-router-dom';

const EmployeeDashboard = () => {
  const [requests, setRequests] = useState([]);
  const [stats, setStats] = useState({ draft: 0, in_progress: 0, approved: 0, rejected: 0 });

  useEffect(() => {
    loadRequests();
  }, []);

  const loadRequests = async () => {
    try {
      const data = await getRequests();
      setRequests(data);
      const statsCalc = {
        draft: data.filter(r => r.status === 'draft').length,
        in_progress: data.filter(r => r.status === 'in_progress').length,
        approved: data.filter(r => r.status === 'approved').length,
        rejected: data.filter(r => r.status === 'rejected').length,
      };
      setStats(statsCalc);
    } catch (error) {
      setRequests([]);
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold tracking-tight">Mes demandes</h1>
        <Link to="/requests/new" className="btn btn-primary">+ Nouvelle demande</Link>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="card"><h3>Brouillons</h3><p className="text-2xl font-bold">{stats.draft}</p></div>
        <div className="card"><h3>En cours</h3><p className="text-2xl font-bold">{stats.in_progress}</p></div>
        <div className="card"><h3>Approuvées</h3><p className="text-2xl font-bold">{stats.approved}</p></div>
        <div className="card"><h3>Rejetées</h3><p className="text-2xl font-bold">{stats.rejected}</p></div>
      </div>

      <div className="card">
        <table>
          <thead>
            <tr><th>Référence</th><th>Type</th><th>Date</th><th>Statut</th><th>Actions</th></tr>
          </thead>
          <tbody>
            {requests.map(req => (
              <tr key={req.id}>
                <td>{req.reference}</td>
                <td>{req.workflowType}</td>
                <td>{new Date(req.createdAt).toLocaleDateString()}</td>
                <td><span className={`status status-${req.status}`}>{req.status}</span></td>
                <td><Link to={`/requests/${req.id}`} className="text-blue-600">Voir</Link></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default EmployeeDashboard;
